#!/bin/bash
# usage: rung.sh <label> <max_items> <max_chars>
set -u
LBL=$1; ITEMS=$2; CHARS=$3

# Every path below is overridable, and none defaults into an ephemeral directory. The
# first version of this script hardcoded the agent job directory it happened to run in
# ($OUT) and then invoked $OUT/emit.py — a copy that no longer exists — so the artifacts
# it produced could not be regenerated by anyone, including its author. A driver whose
# output is committed as evidence has to be runnable from the committed tree.
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO=$(cd "$HERE/../../.." && pwd)
OUT=${OUT:-$HERE}
DD=${DD:-${ZOTEUS_BENCH_DATA:-$HOME/.zoteus-json-baseline}/$LBL}
BENCH=${BENCH:-$REPO/bench}
SERVER=${SERVER:-$REPO/fork/dist/index.js}
EMIT=${EMIT:-$HERE/emit.py}
NOPT=${NOPT:---max-old-space-size=12288}
mkdir -p "$DD" "$OUT"
cd "$BENCH"
echo "=== BUILD $LBL items=$ITEMS chars=$CHARS $(date -Is) ==="
python3 -u run_build.py --server "$SERVER" --data-dir "$DD" --backend json --build \
  --max-items "$ITEMS" --max-chars "$CHARS" --node-options=$NOPT --poll 15 --max-wait 7200 \
  > "$OUT/build-$LBL.log" 2>&1
BRC=$?
echo "build exit $BRC $(date -Is)"
ls -la "$DD"
echo "=== ATREST $LBL $(date -Is) ==="
python3 -u query.py --server "$SERVER" --data-dir "$DD" --backend json \
  --queries-file queries.txt --node-options=$NOPT \
  --out "$OUT/atrest-$LBL.raw.json" > "$OUT/atrest-$LBL.log" 2>&1
ARC=$?
echo "atrest exit $ARC $(date -Is)"
python3 "$EMIT" --rung "$LBL" --data-dir "$DD" --max-items "$ITEMS" --max-chars "$CHARS" \
  --node-options=$NOPT --build-log "$OUT/build-$LBL.log" \
  --atrest-json "$OUT/atrest-$LBL.raw.json" --out "$OUT/rung-$LBL.json" \
  --note "build exit $BRC, atrest exit $ARC"
echo "=== DONE $LBL $(date -Is) ==="
